mapper.select:
select p.*, a.name as app_name, if(p2.cou is null or p2.cou=0,0,1) as is_child FROM permission p join application a on p.app_id = a.id and p.app_id=#{appId} left join ( select p1.pid, count(1) as cou FROM permission p1 where p1.status!=2
and p1.status!=#{status}
group by p1.pid ) p2 on p.id = p2.pid where p.`status`!=2 and p.pid=0
and p.type = #{permissionType}
and p.status=#{status}
and (p.name like concat('%',#{filterVal},'%') or p.sign like concat('%',#{filterVal},'%') )
order by p.created_time desc

select count(1) FROM permission p join application a on p.app_id = a.id and p.app_id=#{appId} left join ( select p1.pid, count(1) as cou FROM permission p1 where p1.status!=2
and p1.status!=#{status}
group by p1.pid ) p2 on p.id = p2.pid where p.`status`!=2 and p.pid=0
and p.type = #{permissionType}
and p.status=#{status}
and (p.name like concat('%',#{filterVal},'%') or p.sign like concat('%',#{filterVal},'%') )

select p.* from permission p join roles_permission rp on p.id = rp.permission_id and p.status = 1 and (p.button_type is null or p.button_type = 2) join( select r.id from role r where r.id in( SELECT DISTINCT dr.role_id from depts_roles dr where dr.dept_id in
#{item}
union SELECT DISTINCT gr.role_id from groups_roles gr join groups_users gu on gr.group_id = gu.group_id and gu.user_id = #{userId} union SELECT DISTINCT ur.role_id from users_roles ur where ur.user_id=#{userId} ) and r.status=1 and r.type=1 )r on rp.role_id = r.id union select p.* from permission p join( select r.app_id from role r where r.id in( SELECT DISTINCT dr.role_id from depts_roles dr where dr.dept_id in
#{item}
union SELECT DISTINCT gr.role_id from groups_roles gr join groups_users gu on gr.group_id = gu.group_id and gu.user_id = #{userId} union SELECT DISTINCT ur.role_id from users_roles ur where ur.user_id=#{userId} ) and r.status=1 and r.type=0 )r on p.app_id = r.app_id
